<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('POST');require_csrf();$user=require_permission('ACLARACION_CREAR');$in=json_input();$movementId=(int)($in['movimiento_id']??0);$title=trim((string)($in['titulo']??''));$desc=trim((string)($in['descripcion']??''));$priority=in_array(($in['prioridad']??'MEDIA'),['BAJA','MEDIA','ALTA'],true)?$in['prioridad']:'MEDIA';$assigned=($in['asignada_a_usuario_id']??'')!==''?(int)$in['asignada_a_usuario_id']:null;if($movementId<=0||$title===''||$desc==='')json_response(['ok'=>false,'error'=>'Movimiento, título y descripción son obligatorios'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$st=$db->prepare("SELECT * FROM presupuesto_movimiento WHERE movimiento_id=?");$st->bind_param('i',$movementId);$st->execute();$mov=$st->get_result()->fetch_assoc();$st->close();if(!$mov||!movement_is_visible($db,$user,$mov)){$db->close();json_response(['ok'=>false,'error'=>'Movimiento no encontrado o fuera de tu alcance'],404);}$folio=next_folio($db,'ACLARACION',(int)$mov['ejercicio']);$uid=(int)$user['user_id'];$st=$db->prepare("INSERT INTO movimiento_aclaracion(folio,movimiento_id,titulo,descripcion,prioridad,estatus,creada_por_usuario_id,asignada_a_usuario_id) VALUES(?,?,?,?,?,'ABIERTA',?,?)");$st->bind_param('sisssii',$folio,$movementId,$title,$desc,$priority,$uid,$assigned);$st->execute();$id=(int)$st->insert_id;$st->close();$st=$db->prepare("INSERT INTO movimiento_aclaracion_mensaje(aclaracion_id,usuario_id,mensaje,es_interno) VALUES(?,?,?,0)");$st->bind_param('iis',$id,$uid,$desc);$st->execute();$st->close();audit_log($db,$uid,'ACLARACION_CREAR','ACLARACION',$id,$folio,null,$in);$db->close();json_response(['ok'=>true,'data'=>['aclaracion_id'=>$id,'folio'=>$folio]]);
